  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Build edges with mutual reachability weight
    edges = []
    for u, v, d in distances:
        w = max(core_distance[u], core_distance[v], d)
        # canonical order for tie-breaking
        if u < v:
            edges.append((w, u, v))
        else:
            edges.append((w, v, u))

    # Sort by weight, then by first endpoint, then second endpoint (strings)
    edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find (Disjoint Set)
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    n_vertices = len(nodes)

    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n_vertices - 1:
                break

    if len(mst_edges) != n_vertices - 1:
        raise ValueError("Disconnected graph: cannot form MST")

    # Sort mst_edges for deterministic output (by weight then endpoints)
    mst_edges.sort(key=lambda e: (e[2], e[0], e[1]))

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }"
}
